"""Perception Rubric evaluator.

The evaluator scores a generated caption with two rubric groups:
- must_right / GroupA: all criteria must pass.
- easy_wrong / GroupB: score is the fraction of passed granular checks.

Final score = all(must_right) * mean(easy_wrong).
"""

from __future__ import annotations

import json
import re
import time
from dataclasses import dataclass
from typing import Any, Dict, Iterable, List, Optional


SCORER_PROMPT = """
You are an expert Rubric Evaluator for Vision-Language Models.

### Task
Your task is to verify whether a model's generated Caption satisfies a specific set of Rubrics (Evaluation Criteria).
You will receive four inputs:
1. Model Caption: The text description generated by the model.
2. Group A (Critical Rubrics): A numbered list of fundamental perception criteria.
3. Group B (Granular Rubrics): A numbered list of fine-grained detail checks.
4. Expected counts for Group A and Group B.

### STRICT RULES: LITERAL INTERPRETATION & FLEXIBLE MATCHING
1. Literal Polarity Only: You MUST evaluate each rubric STRICTLY based on its literal text.
   - DO NOT guess the intent behind the rubric, the dataset design, or why the rubric was created.
   - DO NOT let metadata, variable names (e.g., "easy_wrong", "error_checks"), or group categories influence your judgment.
   - Never reinterpret a positive rubric as a negative hallucination trap.
2. Semantic Equivalence over Exact String Match:
   - DO NOT penalize the model for including extra context, prefixes, suffixes, or using synonymous phrasing.
   - If a rubric requires identifying "X", and the caption states "Y presents X" or includes "X" within a broader string, it is a PASS.
   - Focus on whether the core factual information is present and correct, not on character-for-character exact matching.

### Determining Rubric Polarity & Judgment Logic
Analyze the phrasing of each rubric to determine if it is Positive or Negative, then judge accordingly:

1. Positive Constraints (Keywords: "Must identify", "Must observe", "Must claim", "Mentions"):
   - Requirement: The caption MUST contain or explicitly imply this information.
   - True (Pass): The caption explicitly meets the criteria, implies it without ambiguity, or contains the required target within a broader description.
   - False (Fail): The caption contradicts the criteria or completely fails to mention the required element.

2. Negative Constraints (Keywords: "Must NOT mention", "No", "Fails to", "Absence of"):
   - Requirement: The caption MUST NOT contain this information (Hallucination/Error check).
   - True (Pass): The caption safely omits the prohibited element.
   - False (Fail): The caption explicitly mentions the prohibited element.

### Crucial Requirement
You must evaluate Group A and Group B independently and return the results in separate lists.
The order of boolean results in the output must strictly match the order of the input rubrics.
Use the rubric IDs only to keep alignment correct:
- Group A rubric `A1` maps to `<Result1>` in `<GroupA>`, `A2` to `<Result2>`, and so on.
- Group B rubric `B1` maps to `<Result1>` in `<GroupB>`, `B2` to `<Result2>`, and so on.
Return exactly one numbered result tag for each input rubric, following the pattern `<Result1>`, `<Result2>`, `<Result3>`, etc. Do not merge, split, skip, or duplicate rubrics.
The number of numbered result tags in `<GroupA>` must equal `expected_must_right_count`.
The number of numbered result tags in `<GroupB>` must equal `expected_easy_wrong_count`.
If you think you made a counting mistake, rewrite the full XML once correctly instead of appending a second `<Assessment>`.

### Output Format
Return the result strictly in valid XML format. Do not use Markdown code blocks.
<Assessment>
  <GroupA>
    <Result1>true</Result1>
    <Result2>false</Result2>
    </GroupA>
  <GroupB>
    <Result1>true</Result1>
    <Result2>true</Result2>
    </GroupB>
</Assessment>
""".strip()


@dataclass(frozen=True)
class RubricGroups:
    must_right: List[str]
    easy_wrong: List[str]


@dataclass(frozen=True)
class EvaluationResult:
    score: float
    correct: bool
    judge_result: Dict[str, List[bool]]
    raw_judge: str
    payload: Dict[str, Any]
    error: Optional[str] = None


def build_indexed_rubrics(items: Iterable[str], prefix: str) -> List[Dict[str, str]]:
    return [
        {"id": f"{prefix}{idx}", "rubric": str(rubric)}
        for idx, rubric in enumerate(items, start=1)
    ]


def normalize_rubrics(value: Any) -> List[Dict[str, str]]:
    """Normalize common public dataset formats into [{type, rubric}, ...]."""
    if value is None:
        return []
    if isinstance(value, str):
        try:
            return normalize_rubrics(json.loads(value))
        except json.JSONDecodeError:
            return []
    if isinstance(value, dict):
        if isinstance(value.get("rubrics"), list):
            return normalize_rubrics(value["rubrics"])
        normalized: List[Dict[str, str]] = []
        for key, rubric_type in (
            ("must_right", "must_right"),
            ("group_a", "must_right"),
            ("easy_wrong", "easy_wrong"),
            ("group_b", "easy_wrong"),
        ):
            items = value.get(key)
            if not isinstance(items, list):
                continue
            for item in items:
                if isinstance(item, str):
                    rubric_text = item.strip()
                    if rubric_text:
                        normalized.append({"type": rubric_type, "rubric": rubric_text})
                elif isinstance(item, dict):
                    rubric_text = str(item.get("rubric", "")).strip()
                    if rubric_text:
                        normalized.append(
                            {
                                "type": str(item.get("type", rubric_type)).strip() or rubric_type,
                                "rubric": rubric_text,
                            }
                        )
        return normalized
    if isinstance(value, list):
        normalized = []
        for item in value:
            if isinstance(item, dict):
                rubric_text = str(item.get("rubric", "")).strip()
                if rubric_text:
                    normalized.append(
                        {
                            "type": str(item.get("type", "must_right")).strip() or "must_right",
                            "rubric": rubric_text,
                        }
                    )
            elif isinstance(item, str):
                rubric_text = item.strip()
                if rubric_text:
                    normalized.append({"type": "must_right", "rubric": rubric_text})
        return normalized
    return []


def split_rubrics(rubrics: List[Dict[str, str]]) -> RubricGroups:
    must_right: List[str] = []
    easy_wrong: List[str] = []
    for item in rubrics:
        rubric_type = str(item.get("type", "")).strip().lower()
        rubric_text = str(item.get("rubric", "")).strip()
        if not rubric_text:
            continue
        if rubric_type in {"must_right", "group_a", "a", "critical"}:
            must_right.append(rubric_text)
        elif rubric_type in {"easy_wrong", "group_b", "b", "granular"}:
            easy_wrong.append(rubric_text)
    return RubricGroups(must_right=must_right, easy_wrong=easy_wrong)


def build_judge_payload(caption: str, rubrics: Any) -> Dict[str, Any]:
    groups = split_rubrics(normalize_rubrics(rubrics))
    if not groups.must_right or not groups.easy_wrong:
        raise ValueError("Each sample must include non-empty must_right and easy_wrong rubrics")
    return {
        "must_right": build_indexed_rubrics(groups.must_right, "A"),
        "easy_wrong": build_indexed_rubrics(groups.easy_wrong, "B"),
        "expected_must_right_count": len(groups.must_right),
        "expected_easy_wrong_count": len(groups.easy_wrong),
        "caption": caption,
    }


def hide_thinking_content_for_preview(output: str) -> str:
    """Hide chain-of-thought blocks before logging parser errors."""
    if not output:
        return output

    def replace_block(match: re.Match[str]) -> str:
        tag = match.group(1)
        return f"<{tag}>[hidden]</{tag}>"

    sanitized = re.sub(
        r"<\s*(think|thinking)\b[^>]*>[\s\S]*?<\s*/\s*\1\s*>",
        replace_block,
        output,
        flags=re.IGNORECASE,
    )
    sanitized = re.sub(
        r"<\s*(think|thinking)\b[^>]*>[\s\S]*$",
        lambda match: f"<{match.group(1)}>[hidden]",
        sanitized,
        flags=re.IGNORECASE,
    )
    return sanitized


def raw_output_preview(output: str, max_chars: int = 1000) -> str:
    return hide_thinking_content_for_preview(str(output or ""))[:max_chars].replace("\n", "\\n")


def parse_scorer_response(
    response: str,
    expected_must_right_count: Optional[int] = None,
    expected_easy_wrong_count: Optional[int] = None,
) -> Dict[str, List[bool]]:
    if not response or not isinstance(response, str):
        raise ValueError("Response must be a non-empty string")

    response = response.strip()
    candidates: List[str] = []
    candidates.extend(block.strip() for block in re.findall(r"```(?:xml)?\s*\n?(.*?)\n?```", response, re.DOTALL))
    candidates.extend(re.findall(r"(<Assessment[\s\S]*?</Assessment>)", response, re.DOTALL))
    if response.startswith("<Assessment") and response.endswith("</Assessment>"):
        candidates.insert(0, response)

    def parse_result_text(text: str) -> bool:
        normalized = (text or "").strip().lower()
        if normalized in {"true", "1", "yes"}:
            return True
        if normalized in {"false", "0", "no"}:
            return False
        raise ValueError(f"Invalid result value: {text!r}")

    errors: List[str] = []
    parsed_candidates: List[Dict[str, List[bool]]] = []
    for candidate in candidates:
        if not candidate:
            continue
        group_a_match = re.search(r"<\s*GroupA\s*>(.*?)<\s*/\s*GroupA\s*>", candidate, re.DOTALL | re.IGNORECASE)
        group_b_match = re.search(r"<\s*GroupB\s*>(.*?)<\s*/\s*GroupB\s*>", candidate, re.DOTALL | re.IGNORECASE)
        if not group_a_match or not group_b_match:
            errors.append("Missing GroupA or GroupB in XML")
            continue

        def extract_results(group_text: str) -> List[bool]:
            return [
                parse_result_text(match.group(1))
                for match in re.finditer(
                    r"<\s*Result(?:\d+)?\s*>(.*?)<\s*/\s*Result(?:\d+)?\s*>",
                    group_text,
                    re.DOTALL | re.IGNORECASE,
                )
            ]

        parsed = {
            "must_right": extract_results(group_a_match.group(1)),
            "easy_wrong": extract_results(group_b_match.group(1)),
        }
        if not parsed["must_right"] or not parsed["easy_wrong"]:
            errors.append("Empty results in GroupA or GroupB")
            continue
        parsed_candidates.append(parsed)
        counts_match = (
            (expected_must_right_count is None or len(parsed["must_right"]) == expected_must_right_count)
            and (expected_easy_wrong_count is None or len(parsed["easy_wrong"]) == expected_easy_wrong_count)
        )
        if counts_match:
            return parsed

    error_msg = f"Failed to parse valid scorer XML. Response preview: {raw_output_preview(response, 200)}..."
    if parsed_candidates:
        summaries = [
            f"candidate_{idx + 1}=(GroupA={len(item['must_right'])}, GroupB={len(item['easy_wrong'])})"
            for idx, item in enumerate(parsed_candidates[:5])
        ]
        expected_parts = []
        if expected_must_right_count is not None:
            expected_parts.append(f"GroupA={expected_must_right_count}")
        if expected_easy_wrong_count is not None:
            expected_parts.append(f"GroupB={expected_easy_wrong_count}")
        if expected_parts:
            error_msg += f" Expected counts: {', '.join(expected_parts)}."
        error_msg += f" Parsed candidate counts: {', '.join(summaries)}."
    if errors:
        error_msg += f" Errors: {'; '.join(errors[:3])}"
    raise ValueError(error_msg)


def compute_score(must_right: List[bool], easy_wrong: List[bool]) -> float:
    must_right_ok = all(must_right) if must_right else False
    easy_wrong_score = sum(1 for item in easy_wrong if item) / len(easy_wrong) if easy_wrong else 0.0
    return (1.0 if must_right_ok else 0.0) * easy_wrong_score


def evaluate_with_raw_judge(caption: str, rubrics: Any, raw_judge: str) -> EvaluationResult:
    payload = build_judge_payload(caption, rubrics)
    parsed = parse_scorer_response(
        raw_judge,
        expected_must_right_count=payload["expected_must_right_count"],
        expected_easy_wrong_count=payload["expected_easy_wrong_count"],
    )
    score = compute_score(parsed["must_right"], parsed["easy_wrong"])
    return EvaluationResult(
        score=score,
        correct=score > 0,
        judge_result=parsed,
        raw_judge=raw_judge,
        payload=payload,
    )


class OpenAICompatibleJudge:
    """Small wrapper for OpenAI-compatible chat completion APIs."""

    def __init__(
        self,
        model: str,
        api_key: Optional[str] = None,
        base_url: Optional[str] = None,
        temperature: float = 0.0,
        max_tokens: int = 32768,
        reasoning_effort: Optional[str] = None,
        top_p: Optional[float] = None,
        top_k: Optional[int] = None,
    ) -> None:
        try:
            from openai import OpenAI
        except ImportError as exc:
            raise ImportError("Install the optional dependency with `pip install openai`.") from exc

        kwargs: Dict[str, Any] = {}
        if api_key:
            kwargs["api_key"] = api_key
        if base_url:
            kwargs["base_url"] = base_url
        self.client = OpenAI(**kwargs)
        self.model = model
        self.temperature = temperature
        self.max_tokens = max_tokens
        self.reasoning_effort = reasoning_effort
        self.top_p = top_p
        self.top_k = top_k

    def judge(self, payload: Dict[str, Any]) -> str:
        kwargs: Dict[str, Any] = dict(
            model=self.model,
            messages=[
                {"role": "system", "content": SCORER_PROMPT},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
            temperature=self.temperature,
            max_tokens=self.max_tokens,
        )
        if self.reasoning_effort:
            kwargs["reasoning_effort"] = self.reasoning_effort
        if self.top_p is not None:
            kwargs["top_p"] = self.top_p
        if self.top_k is not None:
            kwargs["extra_body"] = {"top_k": self.top_k}
        response = self.client.chat.completions.create(**kwargs)
        message = response.choices[0].message
        content = message.content or ""
        reasoning = getattr(message, "reasoning_content", None)
        if reasoning:
            return f"<think>\n{reasoning}\n</think>\n\n{content}"
        return content


def evaluate_caption(
    caption: str,
    rubrics: Any,
    judge: OpenAICompatibleJudge,
    retry_times: int = 5,
    retry_sleep_seconds: float = 2.0,
) -> EvaluationResult:
    payload = build_judge_payload(caption, rubrics)
    last_raw_judge = ""
    last_error: Optional[str] = None
    for attempt in range(max(1, retry_times)):
        try:
            last_raw_judge = judge.judge(payload)
            parsed = parse_scorer_response(
                last_raw_judge,
                expected_must_right_count=payload["expected_must_right_count"],
                expected_easy_wrong_count=payload["expected_easy_wrong_count"],
            )
            score = compute_score(parsed["must_right"], parsed["easy_wrong"])
            return EvaluationResult(
                score=score,
                correct=score > 0,
                judge_result=parsed,
                raw_judge=last_raw_judge,
                payload=payload,
            )
        except Exception as exc:  # Keep CLI robust for batch evaluation.
            last_error = str(exc)
            if attempt < retry_times - 1:
                time.sleep(min(30.0, retry_sleep_seconds * (2 ** attempt)))

    return EvaluationResult(
        score=0.0,
        correct=False,
        judge_result={"must_right": [], "easy_wrong": []},
        raw_judge=last_raw_judge,
        payload=payload,
        error=last_error,
    )
